-- ParadiseRP - catalogue FR propre, trie et valide
SET NAMES utf8mb4;
START TRANSACTION;
DELETE FROM catalog_pages WHERE id BETWEEN 9967400 AND 9967499;
-- #PARADISE_FR_UPDATES_BEGIN
DROP TEMPORARY TABLE IF EXISTS paradise_catalog_fr_tmp;
CREATE TEMPORARY TABLE paradise_catalog_fr_tmp (id BIGINT NOT NULL PRIMARY KEY, page_id INT NOT NULL, catalog_name VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL) ENGINE=InnoDB;
UPDATE catalog_items ci JOIN paradise_catalog_fr_tmp t ON t.id=ci.id SET ci.page_id=t.page_id, ci.catalog_name=CONVERT(t.catalog_name USING utf8mb4);
UPDATE catalog_pages SET visible='0',enabled='0' WHERE id BETWEEN 9967100 AND 9967399;
DROP TEMPORARY TABLE paradise_catalog_fr_tmp;
COMMIT;
